void plato_font_init(plato_font_t *font) {
    if (!font) return;
    memcpy(font->m0, CANONICAL_M0_FONT, sizeof(font->m0));
    memcpy(font->m1, CANONICAL_M1_FONT, sizeof(font->m1));
    memset(font->m2, 0, sizeof(font->m2));
    memset(font->m3, 0, sizeof(font->m3));
}

const uint8_t* plato_font_get_glyph(const plato_font_t *font, plato_charset_t set, uint8_t ch) {
    ch &= 0x7F;
    if (!font) return CANONICAL_M0_FONT[ch];
    switch (set) {
        case PLATO_CHARSET_M1: return font->m1[ch];
        case PLATO_CHARSET_M2: return font->m2[ch];
        case PLATO_CHARSET_M3: return font->m3[ch];
        case PLATO_CHARSET_M0:
        default:               return font->m0[ch];
    }
}

void plato_font_load_glyph(plato_font_t *font, plato_charset_t set, uint8_t ch, const uint8_t bitmap[16]) {
    if (!font || !bitmap) return;
    ch &= 0x7F;
    if (set == PLATO_CHARSET_M2) {
        memcpy(font->m2[ch], bitmap, 16);
    } else if (set == PLATO_CHARSET_M3) {
        memcpy(font->m3[ch], bitmap, 16);
    }
}
